insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$cordeiropolis$q$, $q$https://www.camaracordeiropolis.sp.gov.br/siscam/Documentos/Details?id=84429 (Decreto 6.642/2023; PDF do Siscam handler=Arquivo&id=118587)$q$, $q$Ato oficial de Cordeirópolis: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 31, $q$Dec. 6.642/2023, art. 4º: caminhões, carretas, articulados e superdimensionados acima de 6 t proibidos 24 h em 6 vias centrais e de acesso (I a VI, com a Estrada Municipal Carmelo Fior COR 010); exceções só do art. 10. 'Acima de 6 t' lido como capacidade de carga (o art. 2º usa capacidade): confiança média. O art. 9º (PBT acima de 24 t ou tri-articulado no município) fica desativado (verificador: contradiz os arts. 3º, 5º, 11 e 13).$q$);
